    facts: {
      de: ["Grenzübergang zu Dongxing in China.", "Großer Grenzübergangsmarkt.", "Der Strand Trà Cổ ist in der Nähe."],
      hu: ["Határátkelő a kínai Dongxing felé.", "Nagy határpiac.", "A Trà Cổ strand a közelben van."],
      ro: ["Punct de trecere a frontierei către Dongxing, China.", "Piață mare de frontieră.", "Plaja Trà Cổ este în apropiere."],
      en: ["Border crossing to Dongxing, China.", "Large border market.", "Trà Cổ beach is nearby."],
      es: ["Paso fronterizo a Dongxing en China.", "Gran mercado transfronterizo.", "La playa de Trà Cổ está cerca."],
      pt: ["Passagem de fronteira para Dongxing, na China.", "Grande mercado fronteiriço.", "A praia de Trà Cổ fica nas proximidades."],
      fr: ["Poste frontière vers Dongxing en Chine.", "Grand marché transfrontalier.", "La plage de Trà Cổ se trouve à proximité."],
    }, image: "/poi-images/mong-cai-cities-v2.webp",
    descriptionAdvanced: {
      de: "Móng Cái ist eine bedeutende Grenzstadt im Nordosten Vietnams, direkt an der Grenze zur chinesischen Provinz Guangxi gelegen. Sie gehört zur Provinz Quảng Ninh und dient als wichtiger Knotenpunkt für den Handel zwischen den beiden Ländern über die Ka-Long-Brücke. Geographisch zeichnet sich die Stadt durch ihre Küstenlage am Golf von Tonkin aus, wobei der nahegelegene Trà-Cổ-Strand mit einer Länge von etwa 17 Kilometern zu den längsten Sandstränden des Landes zählt. Historisch entwickelte sich der Ort von einem kleinen Grenzdorf zu einer strategisch wichtigen Wirtschaftszone, die 2008 offiziell den Status einer Stadt erhielt. Kulturell ist das Kap Sa Vĩ von großer Bedeutung, da es den nordöstlichsten Punkt des vietnamesischen Festlands markiert und ein markantes Grenzdankmal beherbergt. Heute ist Móng Cái ein Zentrum für Tourismus und grenzüberschreitenden Warenverkehr, das durch moderne Infrastrukturprojekte stetig wächst.",
      hu: "Móng Cái egy stratégiailag kiemelt határváros Vietnám északkeleti részén, Quảng Ninh tartományban, közvetlenül a kínai határ mentén. A város a Ka Long-folyó partján fekszik, amely természetes határt képez a két ország között, és fontos kereskedelmi kapuként szolgál a kínai Guangxi tartomány felé. Gazdasági jelentőségét a 20. század végén létrehozott különleges gazdasági övezet alapozta meg, amely azóta az ország egyik legforgalmasabb határátkelőjévé tette. A település történelme szorosan összefonódik a határ menti kereskedelemmel és a tengerparti halászattal. Itt található a Trà Cổ-part, amely több mint 15 kilométeres hosszával Vietnám egyik legszebb és leghosszabb természetes homokos strandja. A kulturális örökség részét képezi a Sa Vĩ-fok, amely az ország legészakkeletibb pontját jelöli, és ahol egy látványos emlékmű hirdeti a nemzeti szuverenitást. Móng Cái modern várossá fejlődése 2008-ban érte el csúcspontját, amikor hivatalosan is városi rangot kapott.",
      ro: "Móng Cái este un oraș de frontieră strategic situat în nord-estul Vietnamului, în provincia Quảng Ninh, chiar la granița cu Republica Populară Chineză. Orașul este separat de orașul chinez Dongxing prin râul Ka Long, fiind un punct vital pentru schimburile comerciale și turistice transfrontaliere. Din punct de vedere geografic, Móng Cái beneficiază de o deschidere largă la Golful Tonkin, găzduind faimoasa plajă Trà Cổ, considerată una dintre cele mai lungi și mai pitorești plaje virgine din țară, cu o lungime de aproximativ 17 kilometri. Istoria orașului a fost marcată de evoluția sa de la un mic avanpost comercial la o zonă economică specială înfloritoare, statut confirmat prin ridicarea la rangul de oraș în anul 2008. Un punct de referință cultural și simbolic este Capul Sa Vĩ, care marchează extremitatea nord-estică a teritoriului vietnamez, unde se află un impresionant monument al suveranității. În prezent, Móng Cái reprezintă un motor economic regional, combinând infrastructura modernă de transport cu un potențial turistic maritim semnificativ.",
      en: "Móng Cái is a pivotal border city located in the northeastern corner of Vietnam within Quảng Ninh Province, directly adjacent to the Chinese border. The city sits on the banks of the Ka Long River, which serves as a natural boundary and a historic conduit for trade with the neighboring Chinese city of Dongxing. Geographically, it is distinguished by its coastal location along the Gulf of Tonkin, featuring the Trà Cổ beach, which stretches for nearly 17 kilometers and is renowned as one of the country's longest natural beaches. The city's history is characterized by its transformation from a modest trading post into a major special economic zone, officially achieving city status in 2008. A site of great national significance is Sa Vĩ Cape, representing the northeasternmost point of mainland Vietnam and housing a landmark monument. Today, Móng Cái thrives as a commercial hub and a developing tourist destination, playing a crucial role in the economic integration of the region through its modern port and border infrastructure.",
      es: "Móng Cái representa un punto estratégico en la geografía vietnamita, siendo un puesto comercial vital en la provincia de Quảng Ninh. Cuenta con un gran mercado fronterizo que conecta con Dongxing en China y se encuentra cerca de la playa de Trà Cổ. Como parte de los asentamientos característicos de Vietnam, Móng Cái une el dinamismo comercial con la herencia cultural milenaria y el legado francés, enriqueciendo el perfil del país desde el delta del Mekong hasta la bahía de Halong.",
      pt: "Móng Cái é um elemento notável da geografia e cultura vietnamitas. Uma cidade fronteiriça na província de Quảng Ninh, um importante posto comercial entre o Vietnã e a China. Possui um grande mercado fronteiriço e a praia de Trà Cổ está nas proximidades. Esta cidade combina particularidades regionais com a herança de uma civilização milenar e do período colonial francês, contribuindo para o perfil diversificado do país.",
      fr: "Móng Cai est un élément remarquable de la géographie et de la culture vietnamiennes. Ville frontalière de la province de Quảng Ninh, elle est un poste de traite majeur entre le Vietnam et la Chine. Dotée d'un grand marché transfrontalier et proche de la plage de Trà Cổ, elle mêle particularités régionales, héritage d'une civilisation millénaire et époque coloniale française.",
    },
