      hu: ["Határátkelő a kínai Hekou felé.", "Fontos közlekedési csomópont.", "Kiindulópont a Sa Pa-i utazásokhoz."],
      ro: ["Punct de trecere a frontierei către Hekou, China.", "Nod important de transport.", "Punct de plecare pentru călătoriile către Sa Pa."],
