      ro: ["Orașul a primit statutul administrativ oficial în anul 2004.", "Distanța rutieră până la capitala Hanoi este de circa 290 km.", "Gara din Lào Cai este un punct terminal feroviar major.", "Podul internațional face legătura cu orașul chinez Hekou.", "Centrul urban a fost aproape integral reconstruit după 1979.", "Orașul este poarta principală spre masivul muntos Fansipan."],
