      ro: ["Închisoarea Sơn La a fost construită de francezi în 1908.", "Localitatea a fost ridicată la rangul de oraș în anul 2008.", "Altitudinea medie a zonei urbane este de 600 de metri.", "Hidrocentrala Sơn La a fost inaugurată complet în 2012.", "Drumul național 6 asigură principala legătură cu capitala.", "Orașul se află la o distanță de circa 300 km vest de Hanoi."],
