      es: ["Centro regional en el noroeste, destacado por su agricultura de altura.", "Situada en el territorio de la República Socialista de Vietnam.", "Eje fundamental de la diversidad étnica e identidad regional.", "Reconocida por su historia política y belleza natural."],
