      de: "Eine malerische Küsten- und Grenzstadt nahe Kambodscha, bekannt für ihre Kalksteinhöhlen und Strände.",
      hu: "Festői tengerparti és határváros Kambodzsa közelében, mészkőbarlangjairól és strandjairól ismert.",
