      en: ["Đồng Xoài was officially elevated to city status on December 1, 2018.", "Bình Phước Province provides over 50% of Vietnam's cashew exports.", "The Battle of Đồng Xoài in June 1965 lasted for four days.", "The city is located approximately 100 kilometers north of Ho Chi Minh City.", "The region is home to the largest continuous rubber forest in Vietnam.", "The Be River serves as a critical water source for local agriculture."],
      es: ["La capital de la provincia de Bình Phước, conocida por sus plantaciones de caucho y anacardos.", "Se encuentra en el territorio de la República Socialista de Vietnam.", "Desempeña un papel en la identidad local de la región.", "Conocida por su importancia paisajística o cultural."],
      pt: ["A capital da província de Bình Phước, conhecida pelas suas plantações de borracha e castanha de caju.", "Localiza-se no território da República Socialista do Vietname.", "Desempenha um papel na identidade local da região.", "Conhecida pela sua importância paisagística ou cultural."],
