      fr: ["Centre mondial de la religion Cao Đài, doté d'une architecture unique.", "Située sur le territoire de la République socialiste du Vietnam.", "Joue un rôle dans l'identité locale de la région.", "Connue pour son importance paysagère ou culturelle."],
